/* uptBallot */
INSERT IGNORE INTO TB_CLVBAL (
            CLUB_NUMB
          , VOTE_NUMB
          , USER_NUMB
          , TAGT_NUMB
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{clubNumb}
          , #{voteNumb}
          , #{voterNumb}
          , #{targetNumb}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)

mapper.update:
UPDATE /* uptVoteClosed */
       TM_CLVOTX
   SET VOTE_STAT = 'CLOSED'
     , RSLT_NUMB = #{resultNumb,jdbcType=NUMERIC}
     , CLOS_DATE = CURRENT_TIMESTAMP(6)
     , UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE CLUB_NUMB = #{clubNumb}
   AND VOTE_NUMB = #{voteNumb}
   AND VOTE_STAT = 'OPEN'

UPDATE /* uptElectionCompleted */
       TM_CLOWNX
   SET ELCT_STAT = 'COMPLETED'
     , RSLT_USER = #{winnerNumb}
     , UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE CLUB_NUMB = #{clubNumb}
   AND ELCT_NUMB = #{elctNumb}
   AND ELCT_STAT IN ('OPEN', 'RUNOFF', 'EXTENDED')
